namespace sv_438a1fe729524341aa15f297017121cf.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// Interactive Server components on the same circuit share one instance,
/// so changes in any component are visible everywhere immediately.
/// </summary>
public sealed class ThemeService
{
    private Theme _theme = Theme.System;
    private string _accentColor = "#0d6efd";

    public Theme CurrentTheme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Raised whenever theme or accent color changes.
    /// Components subscribe in OnInitialized and unsubscribe in Dispose.
    /// </summary>
    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@using sv_438a1fe729524341aa15f297017121cf.Services
@rendermode InteractiveServer
@inject ThemeService ThemeSvc
@implements IDisposable

<span class="theme-indicator" style="color: @ThemeSvc.AccentColor;" title="Current theme">
    @GetIcon() @ThemeSvc.CurrentTheme
</span>

@code {
    protected override void OnInitialized() => ThemeSvc.OnChange += HandleChanged;

    private void HandleChanged() => InvokeAsync(StateHasChanged);

    private string GetIcon() => ThemeSvc.CurrentTheme switch
    {
        Theme.Light  => "☀️",
        Theme.Dark   => "🌙",
        Theme.System => "💻",
        _            => "🎨"
    };

    public void Dispose() => ThemeSvc.OnChange -= HandleChanged;
}

@page "/settings"
@using sv_438a1fe729524341aa15f297017121cf.Services
@rendermode InteractiveServer
@inject ThemeService ThemeSvc
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="mb-3">
    <label class="form-label fw-bold">Theme</label>
    <div class="btn-group d-block" role="group">
        @foreach (var t in Enum.GetValues<Theme>())
        {
            <button class="btn @(t == ThemeSvc.CurrentTheme ? "btn-primary" : "btn-outline-secondary")"
                    style="@(t == ThemeSvc.CurrentTheme ? $"background-color:{ThemeSvc.AccentColor};border-color:{ThemeSvc.AccentColor}" : "")"
                    @onclick="() => ThemeSvc.CurrentTheme = t">
                @t
            </button>
        }
    </div>
</div>

<div class="mb-3">
    <label class="form-label fw-bold" for="accentPicker">Accent Color</label>
    <input id="accentPicker" type="color" class="form-control form-control-color"
           value="@ThemeSvc.AccentColor"
           @onchange="e => ThemeSvc.AccentColor = e.Value?.ToString() ?? "#0d6efd"" />
</div>

<div class="alert mt-4" style="border-left: 4px solid @ThemeSvc.AccentColor;">
    <strong>Preview:</strong> Theme is <em>@ThemeSvc.CurrentTheme</em>,
    accent is <span style="color:@ThemeSvc.AccentColor;">@ThemeSvc.AccentColor</span>.
</div>

@code {
    protected override void OnInitialized() => ThemeSvc.OnChange += HandleChanged;

    private void HandleChanged() => InvokeAsync(StateHasChanged);

    public void Dispose() => ThemeSvc.OnChange -= HandleChanged;
}

